   var top=new FlowLayoutPanel{Dock=DockStyle.Fill};top.Controls.Add(new Label{Text="基础类型：",AutoSize=true,Padding=new Padding(0,7,0,0)});var kind=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=280};kind.Items.AddRange(new object[]{"GPIO输出 / 气缸通用","PWM位置舵机","自定义UART驱动","自定义CAN驱动","自定义C/C++设备"});top.Controls.Add(kind);var reset=new Button{Text="按类型建立模板",AutoSize=true,Height=30};reset.Click+=(s,e)=>{string driver=kind.SelectedIndex==0?"gpio_output":kind.SelectedIndex==1?"pwm_servo":"custom";var next=CreateBase(driver);next.Id=template.Id;next.Name=template.Name;next.Version=template.Version;if(kind.SelectedIndex==2||kind.SelectedIndex==3){string key=kind.SelectedIndex==2?"Uart":"Can";next.Parameters.Add(new DeviceParameter{Key=key,Name=kind.SelectedIndex==2?"UART句柄":"CAN句柄",Type="identifier",Default=kind.SelectedIndex==2?"huart1":"hcan2"});next.Resources.Add(new DeviceResource{Kind=kind.SelectedIndex==2?"uart":"can_rx",Value="${"+key+"}",Shared=kind.SelectedIndex==3});next.Category="communication";}template=next;LoadValue();};top.Controls.Add(reset);top.Controls.Add(new Label{Text="内置模板不被覆盖；同ID/版本内容变更须升版本。GPIO/PWM可直接参数化；未知协议须导入真实驱动。\r\n占位符${参数Key}；额外有${Prefix}/${InstanceId}/${InstanceName}/${InstanceIndex}，仅单次替换。",AutoSize=true});root.Controls.Add(top);kind.SelectedIndex=template.DriverKind=="gpio_output"?0:template.DriverKind=="pwm_servo"?1:4;
   var tabs=new TabControl{Dock=DockStyle.Fill};root.Controls.Add(tabs);var basic=new TabPage("模板属性");properties.Dock=DockStyle.Fill;properties.ToolbarVisible=false;properties.PropertySort=PropertySort.NoSort;basic.Controls.Add(properties);tabs.TabPages.Add(basic);
   Grid(parameters,new[]{"Key","中文名称","类型","默认值","Min","Max","可选值(|分隔)","说明"});Grid(resources,new[]{"资源类型","资源值(${Key})","允许同值共享"});Grid(operations,new[]{"操作ID","中文名称","默认值","Min","Max"});Page(tabs,"参数表单",parameters);Page(tabs,"资源占用",resources);Page(tabs,"操作目录",operations);
   var sourceTab=new TabPage("源文件");var sourceRoot=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2};sourceRoot.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,250));sourceRoot.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));sourceRoot.RowStyles.Add(new RowStyle(SizeType.Percent,100));sourceRoot.RowStyles.Add(new RowStyle(SizeType.Absolute,50));sourceTab.Controls.Add(sourceRoot);files.Dock=DockStyle.Fill;files.HorizontalScrollbar=true;sourceRoot.Controls.Add(files,0,0);filePreview.Dock=DockStyle.Fill;filePreview.Multiline=true;filePreview.ReadOnly=true;filePreview.WordWrap=false;filePreview.ScrollBars=ScrollBars.Both;filePreview.Font=new Font("Consolas",10);sourceRoot.Controls.Add(filePreview,1,0);var sourceButtons=new FlowLayoutPanel{Dock=DockStyle.Fill};sourceRoot.Controls.Add(sourceButtons,0,1);sourceRoot.SetColumnSpan(sourceButtons,2);var import=new Button{Text="导入C/H/C++文件…",AutoSize=true};import.Click+=(s,e)=>ImportFiles();sourceButtons.Controls.Add(import);var addFile=new Button{Text="新增源文件…",AutoSize=true};addFile.Click+=(s,e)=>EditSource(true);sourceButtons.Controls.Add(addFile);var editFile=new Button{Text="编辑选中文件…",AutoSize=true};editFile.Click+=(s,e)=>EditSource(false);sourceButtons.Controls.Add(editFile);var remove=new Button{Text="移除选中文件",AutoSize=true};remove.Click+=(s,e)=>{if(files.SelectedIndex<0)return;template.Files.RemoveAt(files.SelectedIndex);RefreshFiles();};sourceButtons.Controls.Add(remove);files.SelectedIndexChanged+=(s,e)=>filePreview.Text=files.SelectedIndex<0?"":template.Files[files.SelectedIndex].Content;tabs.TabPages.Add(sourceTab);
