  public static DeviceTemplate CreateBase(string kind){
   var existing=HardwareCatalog.Builtins().FirstOrDefault(t=>t.DriverKind==kind);var value=existing==null?new DeviceTemplate():HardwareCatalog.Snapshot(existing);
   value.Id="user_"+Guid.NewGuid().ToString("N");value.Name="我的"+(kind=="gpio_output"?"GPIO设备":kind=="pwm_servo"?"PWM设备":"新硬件");value.Version="1.0.0";value.Verified="none";
   if(kind=="custom"){value.DriverKind="custom";value.Operations.Add(new DeviceOperation{Id="command",Name="发送目标",DefaultValue=0});value.Hooks.Init="return 1;";value.Hooks.Command="/* 调用真实驱动；默认未实现，明确报告失败。 */\nreturn 0;";value.Hooks.Done="/* 不把空操作当成已完成。 */\nreturn 0;";value.Hooks.ReadObservation="return 0;";}
   return value;
  }
  static string Hint(string name){switch(name){case "Service":return "函数内可用now_ms、dt_ms；不得阻塞。服务周期由模板属性指定。";case "Command":return "返回1表示接受，0表示失败；可用operation(const char*)、value(float)。禁止默认成功。";case "Done":return "返回1已完成、0仍在运行；完成需真实反馈或明确声明的时间等待。";case "OnCanRx":return "可用can、header、data；只解析已由统一分发器取出的帧，不再读FIFO。";case "OnUartRx":return "可用uart、data、len；只消费本设备接收数据，保持非阻塞。";case "OnTimer":return "可用timer；在中断上下文执行，避免阻塞、动态分配和复杂解析。";case "ReadObservation":return "可用sample(rcs_observation*)，返回1有效、0无新数据；必须填实际序号/样本年龄。";case "Declarations":return "每个实例会展开一次；static状态名称使用${Prefix}前缀，避免多实例符号冲突。";case "Init":return "返回1初始化成功、0失败。初始化不能未经许可让机构运动；使能/准备应作为显式操作。";case "Stop":return "停止/取消/故障时的真实停机策略；不得重新启动机构。";default:return "包含真实驱动头文件；外设与main初始化由CubeMX管理。";}}
  static void Grid(DataGridView grid,string[] columns){grid.Dock=DockStyle.Fill;grid.AllowUserToAddRows=true;grid.AllowUserToDeleteRows=true;grid.RowHeadersWidth=32;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.EditMode=DataGridViewEditMode.EditOnEnter;foreach(var c in columns)grid.Columns.Add(c,c);}
  static void Page(TabControl tabs,string text,Control control){var page=new TabPage(text);page.Controls.Add(control);tabs.TabPages.Add(page);}
  void LoadValue(){properties.SelectedObject=new TemplateProperties(template);parameters.Rows.Clear();foreach(var p in template.Parameters)parameters.Rows.Add(p.Key,p.Name,p.Type,p.Default,p.Min.ToString(CultureInfo.InvariantCulture),p.Max.ToString(CultureInfo.InvariantCulture),String.Join("|",p.Choices),p.Description);resources.Rows.Clear();foreach(var r in template.Resources)resources.Rows.Add(r.Kind,r.Value,r.Shared?"true":"false");operations.Rows.Clear();foreach(var o in template.Operations)operations.Rows.Add(o.Id,o.Name,o.DefaultValue.ToString(CultureInfo.InvariantCulture),o.Min.ToString(CultureInfo.InvariantCulture),o.Max.ToString(CultureInfo.InvariantCulture));foreach(var pair in code)pair.Value.Text=pair.Key=="Includes"?template.Includes:pair.Key=="Declarations"?template.Declarations:(string)typeof(DeviceHooks).GetProperty(pair.Key).GetValue(template.Hooks,null);RefreshFiles();}
  static string Cell(DataGridViewRow row,int n){return Convert.ToString(row.Cells[n].Value,CultureInfo.InvariantCulture)??"";}
  static double Number(DataGridViewRow row,int n,double fallback){string value=Cell(row,n);double result;if(value=="")return fallback;if(!Double.TryParse(value,NumberStyles.Float,CultureInfo.InvariantCulture,out result)||!MapDocument.Finite(result))throw new Exception("参数表含无效数字："+value);return result;}
  public DeviceTemplate CaptureTemplate(){properties.Focus();parameters.EndEdit();resources.EndEdit();operations.EndEdit();template.Parameters=parameters.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&!String.IsNullOrWhiteSpace(Cell(r,0))).Select(r=>new DeviceParameter{Key=Cell(r,0),Name=Cell(r,1),Type=Cell(r,2),Default=Cell(r,3),Min=Number(r,4,-1000000000),Max=Number(r,5,1000000000),Choices=Cell(r,6).Split(new[]{'|'},StringSplitOptions.RemoveEmptyEntries).ToList(),Description=Cell(r,7)}).ToList();template.Resources=resources.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&!String.IsNullOrWhiteSpace(Cell(r,0))).Select(r=>new DeviceResource{Kind=Cell(r,0),Value=Cell(r,1),Shared=Cell(r,2)=="true"||Cell(r,2)=="1"}).ToList();template.Operations=operations.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&!String.IsNullOrWhiteSpace(Cell(r,0))).Select(r=>new DeviceOperation{Id=Cell(r,0),Name=Cell(r,1),DefaultValue=Number(r,2,0),Min=Number(r,3,-1000000000),Max=Number(r,4,1000000000)}).ToList();foreach(var pair in code){if(pair.Key=="Includes")template.Includes=pair.Value.Text;else if(pair.Key=="Declarations")template.Declarations=pair.Value.Text;else typeof(DeviceHooks).GetProperty(pair.Key).SetValue(template.Hooks,pair.Value.Text,null);}HardwareRules.TemplateCheck(template);return HardwareCatalog.Snapshot(template);}
  void ImportFiles(){using(var dialog=new OpenFileDialog{Filter="C/C++驱动文件|*.c;*.h;*.cpp;*.hpp",Multiselect=true})if(dialog.ShowDialog(this)==DialogResult.OK)try{foreach(var path in dialog.FileNames){string name=Path.GetFileName(path);HardwareRules.SafePath(name);if(template.Files.Any(f=>String.Equals(f.Path,name,StringComparison.OrdinalIgnoreCase)))throw new Exception("同名文件已存在，请先移除或重命名："+name);var bytes=File.ReadAllBytes(path);if(bytes.Length>65536)throw new Exception("单个源文件最大64KB："+name);string text;try{text=new UTF8Encoding(false,true).GetString(bytes);}catch(DecoderFallbackException){text=Encoding.GetEncoding(54936).GetString(bytes);}if(text.IndexOf('\0')>=0)throw new Exception("不能导入二进制文件。");template.Files.Add(new DeviceFile{Path=name,Content=text.Replace("\r\r\n","\n").Replace("\r\n","\n")});}RefreshFiles();}catch(Exception error){MessageBox.Show(this,error.Message,"源文件导入未完成");}}
  void RefreshFiles(){files.Items.Clear();files.Items.AddRange(template.Files.Select(f=>(object)f.Path).ToArray());if(files.Items.Count>0)files.SelectedIndex=0;else filePreview.Text="";}
  void EditSource(bool add){int index=files.SelectedIndex;if(!add&&index<0)return;var value=add?new DeviceFile{Path="my_device.c",Content="/* 真实驱动代码；按本模板生命周期调用。 */\n"}:new DeviceFile{Path=template.Files[index].Path,Content=template.Files[index].Content};using(var dialog=new HardwareSourceFileDialog(value))if(dialog.ShowDialog(this)==DialogResult.OK){if(template.Files.Where((f,i)=>add||i!=index).Any(f=>String.Equals(f.Path,value.Path,StringComparison.OrdinalIgnoreCase))){MessageBox.Show(this,"同名源文件已存在，未覆盖。");return;}if(add)template.Files.Add(value);else template.Files[index]=value;RefreshFiles();}}
  sealed class TemplateProperties {
   readonly DeviceTemplate t;public TemplateProperties(DeviceTemplate value){t=value;}
   [DisplayName("模板名称")]public string Name{get{return t.Name;}set{t.Name=value;}}
   [DisplayName("模板ID（C标识符）")]public string Id{get{return t.Id;}set{t.Id=value;}}
   [DisplayName("模板版本 x.y.z")]public string Version{get{return t.Version;}set{t.Version=value;}}
   [DisplayName("类别 actuator/sensor/communication")]public string Category{get{return t.Category;}set{t.Category=value;}}
   [DisplayName("平台 F407_HAL/F407_STD")]public string Platform{get{return t.Platform;}set{t.Platform=value;}}
   [DisplayName("驱动类型")]public string DriverKind{get{return t.DriverKind;}set{t.DriverKind=value;}}
   [DisplayName("UART 接收完成函数"),Description("可选，配合错误处理函数使用，签名为 void Name(UART_HandleTypeDef *uart)。仅接收模板声明的独占 UART。")]
   public string UartRxCompleteHandler{get{return t.UartRxCompleteHandler;}set{t.UartRxCompleteHandler=String.IsNullOrWhiteSpace(value)?null:value.Trim();}}
   [DisplayName("UART 错误处理函数"),Description("可选，配合接收完成函数使用。驱动负责错误恢复和重新启动接收。")]
   public string UartErrorHandler{get{return t.UartErrorHandler;}set{t.UartErrorHandler=String.IsNullOrWhiteSpace(value)?null:value.Trim();}}
   [DisplayName("支持实例数")]public int MaxInstances{get{return t.MaxInstances;}set{t.MaxInstances=value;}}
   [DisplayName("服务周期 ms")]public int PeriodMs{get{return t.PeriodMs;}set{t.PeriodMs=value;}}
   [DisplayName("最小堆空间 bytes")]public int MinHeapBytes{get{return t.MinHeapBytes;}set{t.MinHeapBytes=value;}}
   [DisplayName("验证声明 none/host/hardware")]public string Verified{get{return t.Verified;}set{t.Verified=value;}}
   [DisplayName("定位观测轴 0/3/4/7")]public int ObservationAxes{get{return t.ObservationAxes;}set{t.ObservationAxes=value;}}
   [DisplayName("定位类型 imu/tracking_encoder/external_pose")]public string ObservationKind{get{return t.ObservationKind;}set{t.ObservationKind=value;}}
   [DisplayName("设备说明")]public string Note{get{return t.Note;}set{t.Note=value;}}
  }
 }
 public sealed class HardwareSourceFileDialog:Form {
  public HardwareSourceFileDialog(DeviceFile file){Text="编辑模板源文件";Size=new Size(920,700);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",10);var root=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,Padding=new Padding(12)};root.RowStyles.Add(new RowStyle(SizeType.Absolute,42));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,45));Controls.Add(root);var name=new TextBox{Dock=DockStyle.Fill,Text=file.Path};root.Controls.Add(name);var body=new TextBox{Dock=DockStyle.Fill,Multiline=true,AcceptsTab=true,AcceptsReturn=true,WordWrap=false,ScrollBars=ScrollBars.Both,Text=file.Content,Font=new Font("Consolas",10)};root.Controls.Add(body);var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var save=new Button{Text="确定",Width=100};save.Click+=(s,e)=>{try{HardwareRules.SafePath(name.Text);if(!new[]{".c",".h",".cpp",".hpp"}.Contains(Path.GetExtension(name.Text))||body.Text.Length>65536||body.Text.Contains("\0"))throw new Exception("源文件须为C/C++文本，最大64KB。");file.Path=name.Text;file.Content=body.Text.Replace("\r\n","\n");file.Resource=null;DialogResult=DialogResult.OK;}catch(Exception error){MessageBox.Show(this,error.Message);}};bar.Controls.Add(save);bar.Controls.Add(new Button{Text="取消",DialogResult=DialogResult.Cancel,Width=100});root.Controls.Add(bar);}
 }
